
#include <bits/stdc++.h>
using namespace std;
struct Q{long long p=0,q=1;};long long gg(long long a,long long b){a=llabs(a);b=llabs(b);while(b){long long t=a%b;a=b;b=t;}return a?a:1;}Q nm(__int128 p,__int128 q){if(q<0)p=-p,q=-q;if(p>LLONG_MAX||p<LLONG_MIN||q>LLONG_MAX)throw overflow_error("Q");long long a=p,b=q,g=gg(a,b);return{a/g,b/g};}Q ad(Q a,Q b){return nm((__int128)a.p*b.q+(__int128)b.p*a.q,(__int128)a.q*b.q);}Q su(Q a,Q b){return nm((__int128)a.p*b.q-(__int128)b.p*a.q,(__int128)a.q*b.q);}Q mu(Q a,Q b){long long x=gg(a.p,b.q),y=gg(b.p,a.q);return nm((__int128)(a.p/x)*(b.p/y),(__int128)(a.q/y)*(b.q/x));}Q dv(Q a,Q b){return mu(a,nm(b.q,b.p));}bool ge(Q a,Q b){return (__int128)a.p*b.q>=(__int128)b.p*a.q;}
bool solve(vector<vector<long long>>z,vector<Q>&x){int n=z.size();vector<vector<Q>>a(n,vector<Q>(n+1));for(int i=0;i<n;i++)for(int j=0;j<=n;j++)a[i][j]={z[i][j],1};for(int c=0;c<n;c++){int p=c;while(p<n&&!a[p][c].p)p++;if(p==n)return 0;swap(a[p],a[c]);Q inv=dv({1,1},a[c][c]);for(int j=c;j<=n;j++)a[c][j]=mu(a[c][j],inv);for(int i=0;i<n;i++)if(i!=c&&a[i][c].p){Q f=a[i][c];for(int j=c;j<=n;j++)a[i][j]=su(a[i][j],mu(f,a[c][j]));}}x.resize(n);for(int i=0;i<n;i++)x[i]=a[i][n];return 1;}
vector<Q> alpha(vector<int>const&M,int n){int m=M.size();vector<int>seen(n),u,s;for(int a:M)for(int i=0;i<n;i++)if(a>>i&1)seen[i]=1;for(int i=0;i<n;i++)(seen[i]?s:u).push_back(i);int need=8-m-u.size();vector<int>p;vector<Q>ans;function<bool(int,int)>rec=[&](int at,int left){if(!left){vector<vector<long long>>B(8,vector<long long>(9));int r=0;for(int c=0;c<m;c++,r++){for(int i=0;i<n;i++)B[r][i]=(M[c]>>i)&1;B[r][8]=1;}for(int i:u){B[r][i]=1;B[r][7]=-1;r++;}for(int z:p){int i=s[z];B[r][i]=1;B[r][7]=-1;r++;}vector<Q>x;if(r!=8||!solve(B,x)||x[7].p<=0)return 0;for(int i=0;i<n;i++)if(!ge(x[i],x[7]))return 0;ans.assign(x.begin(),x.begin()+n);return 1;}for(int z=at;z<=(int)s.size()-left;z++){p.push_back(z);if(rec(z+1,left-1))return 1;p.pop_back();}return 0;};if(!rec(0,need))throw runtime_error("no alpha");return ans;}
int main(int ac,char**av){if(ac!=4)return 2;int n=stoi(av[1]);ifstream f(av[2]);ofstream o(av[3]);string l;long long all=0,yes=0;map<int,long long>c;while(getline(f,l)){stringstream s(l);int m;s>>m;vector<int>M(m);for(int&i:M)s>>i;all++;try{auto a=alpha(M,n);o<<l<<"\n";yes++;c[m]++;}catch(...){}}cerr<<"all "<<all<<" positive "<<yes<<"\n";for(auto z:c)cerr<<z.first<<" "<<z.second<<"\n";}
